const structure = await browserjs(tabId, () => {
  function getTree(node, depth = 0) {
    if (depth > 5) return '...';
    let s = node.nodeName;
    if (node.id) s += '#' + node.id;
    if (node.className) s += '.' + Array.from(node.classList || []).join('.');
    const children = Array.from(node.children || []).map(c => getTree(c, depth + 1));
    return { name: s, children };
  }
  return getTree(document.body);
});
