const tabId = 845789484;
// Enable DOM and get document
await tool.cdp({ tabId, method: "DOM.enable", params: {} });
const doc = await tool.cdp({ tabId, method: "DOM.getDocument", params: { depth: -1, pierce: true } });

// Function to find node with text or attribute
function findNodes(node, matchFn, acc = []) {
  if (matchFn(node)) acc.push(node);
  if (node.children) node.children.forEach(c => findNodes(c, matchFn, acc));
  if (node.shadowRoots) node.shadowRoots.forEach(sr => findNodes(sr, matchFn, acc));
  if (node.contentDocument) findNodes(node.contentDocument, matchFn, acc);
  return acc;
}

const buttons = findNodes(doc.root, n => n.nodeName === 'BUTTON');
console.log("Found buttons:", buttons.map(b => ({
  nodeId: b.nodeId,
  backendNodeId: b.backendNodeId,
  attrs: b.attributes
})));

for (const b of buttons) {
  try {
    const box = await tool.cdp({ tabId, method: "DOM.getBoxModel", params: { nodeId: b.nodeId } });
    console.log("Button box:", b.attributes, box.model.content);
  } catch (e) {
    console.log("Box error for button:", e.message);
  }
}

