const tabId = 845789607;
const results = await browserjs(tabId, () => {
  // Find all cards/items in the results list
  const items = Array.from(document.querySelectorAll('ol li, ul li, [role="listitem"], main button, [data-destination]'));
  const dests = [];

  // Also scan all text elements or buttons with prices
  const buttons = Array.from(document.querySelectorAll('button'));
  for (const b of buttons) {
    const text = b.innerText;
    if (text.includes('£') && (text.includes('Non-stop') || text.includes('stop') || text.includes('Nov'))) {
      dests.push(text.replace(/\n+/g, ' | '));
    }
  }
  return {
    buttonCount: dests.length,
    dests: Array.from(new Set(dests)).slice(0, 30)
  };
});
console.log(JSON.stringify(results, null, 2));

