const tabId = 845789607;
const fullData = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('main h3'));
  return headings.map(h => {
    // Find the enclosing button or container
    let p = h;
    while (p && p.tagName !== 'BUTTON' && p !== document.body) {
      p = p.parentElement;
    }
    const text = p ? p.innerText : '';
    // Look for price like £34 or 34 British pounds
    const priceMatch = text.match(/£(\d+)/) || text.match(/(\d+)\s+British pounds/);
    const nonStop = text.includes('Non-stop');
    const stopsMatch = text.match(/(\d+)\s+stops?/);
    const durationMatch = text.match(/(\d+\s*hrs?(?:\s*\d+\s*min)?|\d+\s*min)/);
    const airlineMatch = text.match(/(Ryanair(?:\s*UK)?|easyJet|British Airways|Wizz Air|Aegean|SWISS|Lufthansa|Vueling|Iberia|TAP|Air France|KLM|Jet2)/i);

    return {
      destination: h.innerText.trim(),
      price: priceMatch ? `£${priceMatch[1]}` : null,
      priceNum: priceMatch ? parseInt(priceMatch[1], 10) : null,
      stops: nonStop ? 'Non-stop' : (stopsMatch ? stopsMatch[0] : 'Unknown'),
      duration: durationMatch ? durationMatch[0] : null,
      airline: airlineMatch ? airlineMatch[0] : null,
      rawText: text.replace(/\n+/g, ' | ')
    };
  });
});
console.log(JSON.stringify(fullData, null, 2));

