  const h2s = Array.from(document.querySelectorAll('h2'));
  for (const h of h2s) {
    let p = h.parentElement;
    for (let i = 0; i < 4; i++) {
      if (!p) break;
      const text = p.innerText;
      const priceMatch = text.match(/(?:Prices starting from\s+)?([$£]\d+)/);
      const ratingMatch = text.match(/(\d\.\d)\s+out of 5 stars/);
      if (priceMatch && !cards.find(c => c.name === h.innerText.trim())) {
        cards.push({
          name: h.innerText.trim(),
          price: priceMatch[1],
          rating: ratingMatch ? ratingMatch[1] : null,
          details: text.slice(0, 200).replace(/\n+/g, ' | ')
        });
        break;
      }
      p = p.parentElement;
    }
  }
  return cards;
});
console.log("Rome hotels:", JSON.stringify(romeHotels.slice(0, 10), null, 2));

