const tabId = 845789607;

const weatherUrls = {
  seville: "https://www.holiday-weather.com/seville/averages/november/",
  rome: "https://www.holiday-weather.com/rome/averages/november/",
  lisbon: "https://www.holiday-weather.com/lisbon/averages/november/"
};

const weatherData = {};

for (const [city, u] of Object.entries(weatherUrls)) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  const text = await browserjs(tabId, () => {
    const t = document.body.innerText;
    const high = t.match(/High Temperature\s*\|\s*(\d+°C|\d+º)/i) || t.match(/High\s*\|\s*(\d+°C)/i);
    const low = t.match(/Low Temperature\s*\|\s*(\d+°C|\d+º)/i) || t.match(/Low\s*\|\s*(\d+°C)/i);
    const avg = t.match(/Temperature\s*\|\s*(\d+°C|\d+º)/i);
    const sunshine = t.match(/Sunshine Hours\s*\|\s*([^|\n]+)/i);
    const rainfallDays = t.match(/Rainfall Days\s*\|\s*([^|\n]+)/i);
    const rainfall = t.match(/Rainfall\s*\|\s*([^|\n]+)/i);
    return {
      high: high ? high[1] : null,
      low: low ? low[1] : null,
      avg: avg ? avg[1] : null,
      sunshine: sunshine ? sunshine[1].trim() : null,
      rainfallDays: rainfallDays ? rainfallDays[1].trim() : null,
      rainfall: rainfall ? rainfall[1].trim() : null,
      snippet: t.slice(t.indexOf("Weather in November"), t.indexOf("Weather in November") + 500).replace(/\n+/g, ' | ')
    };
  });
  weatherData[city] = text;
}

console.log("Weather data for all finalists:", JSON.stringify(weatherData, null, 2));

